import requests,time,json,re; from urllib.parse import urljoin;
for base in ['https://pypi.mirrors.ustc.edu.cn/simple/lief/','https://mirrors.aliyun.com/pypi/simple/lief/']:
 try:
  r=requests.get(base,timeout=10); links=re.findall(r'href=[\"\x27]([^\"\x27]+)',r.text); match=next((x.split('#')[0] for x in links if 'lief-1.0.0-cp312-abi3-manylinux_2_28_x86_64.whl' in x),None); start=time.monotonic(); n=0; f=requests.get(urljoin(r.url,match),stream=True,timeout=10) if match else None
  if f:
   for part in f.iter_content(65536):
    n+=len(part)
    if n>=262144:break
   f.close()
  elapsed=time.monotonic()-start; print(json.dumps({'index':base,'index_status':r.status_code,'wheel_status':f.status_code if f is not None else None,'bytes':n,'seconds':round(elapsed,2),'kbytes_per_second':round(n/1024/max(elapsed,.001),1)}),flush=True)
 except Exception as exc:print(json.dumps({'index':base,'error_type':type(exc).__name__}),flush=True)
